#!/usr/bin/env node
// Generates the typed catalogs (`Item`, `Ball`) from the game's public data.
//
//   node scripts/generate-catalog.mjs            write the generated files (downloads the public items catalog)
//   node scripts/generate-catalog.mjs --check    exit 1 if the generated files are out of date with the game
//
// Items come from the game's public `assets/items.json`. Balls are not in that file: the server sends them in the
// `welcome` packet, so `packages/sdk/data/balls.json` is a snapshot of that catalog (game data only, nothing about an
// account). The same goes for the game's own items (`itensNossos` in that packet: boss tokens, eggs, fragments...),
// kept in `packages/sdk/data/extra-items.json` when present. The test extension has a button that copies both.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const SDK = path.join(ROOT, 'packages/sdk');
const ITEMS_URL = 'https://pokeidle.io/assets/items.json';
const BALLS_SNAPSHOT = path.join(SDK, 'data/balls.json');
const EXTRA_ITEMS_SNAPSHOT = path.join(SDK, 'data/extra-items.json');
const OUT_ITEMS = path.join(SDK, 'src/catalog/items.generated.ts');
const OUT_BALLS = path.join(SDK, 'src/catalog/balls.generated.ts');
const OUT_NPC_SHOP = path.join(SDK, 'src/catalog/npc-shop.generated.ts');

const args = new Set(process.argv.slice(2));
const check = args.has('--check');

/** "Air Tank" -> "AirTank". Letters and digits only; a leading digit gets an underscore so the key is a valid identifier. */
export function identifierFor(name) {
  // Accents are removed first ('Poké Ball' -> 'Poke Ball'), then anything that is not a letter or digit separates words.
  const words =
    String(name)
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/['’`]/g, '')
      .match(/[A-Za-z0-9]+/g) ?? [];
  const key = words.map((w) => w[0].toUpperCase() + w.slice(1)).join('');
  return /^[0-9]/.test(key) ? `_${key}` : key;
}

/**
 * Unique identifiers for a list of `{ id, name }`. When several entries share a name, the lowest id keeps the clean
 * identifier (new entries usually get higher ids, so existing keys stay stable) and the others get `_<id>`.
 */
export function uniqueIdentifiers(entries) {
  const byBase = new Map();
  for (const entry of [...entries].sort((a, b) => a.id - b.id)) {
    const base = identifierFor(entry.name);
    if (!base || base === '_') throw new Error(`cannot build an identifier from the name ${JSON.stringify(entry.name)} (id ${entry.id})`);
    (byBase.get(base) ?? byBase.set(base, []).get(base)).push(entry);
  }
  const out = [];
  for (const [base, group] of byBase)
    group.forEach((entry, index) => out.push({ ...entry, key: index === 0 ? base : `${base}_${entry.id}` }));
  return out.sort((a, b) => a.id - b.id);
}

const isInt = (v) => Number.isInteger(v) && v >= 0;
const str = (v) => JSON.stringify(String(v));

function validateItems(raw) {
  const list = Array.isArray(raw?.items) ? raw.items : null;
  if (!list || list.length === 0) throw new Error('items catalog: expected { items: [...] }');
  const seen = new Set();
  return list.map((i) => {
    if (!isInt(i?.id) || typeof i.name !== 'string' || typeof i.category !== 'string')
      throw new Error(`items catalog: bad entry ${JSON.stringify(i)}`);
    if (seen.has(i.id)) throw new Error(`items catalog: duplicated id ${i.id}`);
    seen.add(i.id);
    return { id: i.id, name: i.name, category: i.category, rare: i.rare === true, npcPrice: isInt(i.npcPrice) ? i.npcPrice : null };
  });
}

function validateBalls(raw) {
  if (!Array.isArray(raw) || raw.length === 0) throw new Error('balls snapshot: expected a non-empty array');
  const seen = new Set();
  return raw.map((b) => {
    if (!isInt(b?.id) || typeof b.name !== 'string') throw new Error(`balls snapshot: bad entry ${JSON.stringify(b)}`);
    if (seen.has(b.id)) throw new Error(`balls snapshot: duplicated id ${b.id}`);
    seen.add(b.id);
    return {
      id: b.id,
      name: b.name,
      catchRate: isInt(b.catchRate) ? b.catchRate : null,
      priceGold: isInt(b.priceGold) ? b.priceGold : null,
      buyable: b.buyable === true,
    };
  });
}

const HEADER = (source) => `// GENERATED by scripts/generate-catalog.mjs from ${source}. Do not edit by hand: run \`npm run catalog\`.\n`;

function renderItems(items) {
  const keyed = uniqueIdentifiers(items);
  const categories = [...new Set(items.map((i) => i.category))].sort();
  const lines = [HEADER("the game's public items catalog"), '/** Item ids by name, e.g. `Item.SmallPotion`. */', 'export const Item = {'];
  for (const i of keyed) lines.push(`  ${i.key}: ${i.id},`);
  lines.push('} as const;', '', 'export type ItemId = (typeof Item)[keyof typeof Item];', '');
  lines.push(`export type ItemCategory = ${categories.map(str).join(' | ')};`, '');
  lines.push(
    'export interface ItemInfo {',
    '  readonly id: number;',
    '  readonly name: string;',
    '  readonly category: ItemCategory;',
    '  readonly rare: boolean;',
    '  /** What an NPC pays for it, if the catalog says. */',
    '  readonly npcPrice: number | null;',
    '}',
    '',
  );
  lines.push('export const ITEM_CATALOG: readonly ItemInfo[] = [');
  for (const i of keyed)
    lines.push(`  { id: ${i.id}, name: ${str(i.name)}, category: ${str(i.category)}, rare: ${i.rare}, npcPrice: ${i.npcPrice} },`);
  lines.push('];', '');
  return lines.join('\n');
}

/** The potions and revives the NPC shop sells: not rare, with a price (checked against real purchases). */
export function npcShopItems(items) {
  return items.filter((i) => (i.category === 'heal' || i.category === 'revive') && !i.rare && i.npcPrice !== null && i.npcPrice > 0);
}

function renderNpcShop(items) {
  const lines = [
    HEADER("the game's public items catalog"),
    '/** What the NPC shop sells besides balls (potions and revives), with its price per unit. Small on purpose: the full catalog is separate. */',
    'export const NPC_SHOP_ITEMS: readonly { readonly id: number; readonly name: string; readonly price: number }[] = [',
  ];
  for (const i of npcShopItems(items)) lines.push(`  { id: ${i.id}, name: ${str(i.name)}, price: ${i.npcPrice} },`);
  lines.push('];', '');
  return lines.join('\n');
}

function renderBalls(balls) {
  const keyed = uniqueIdentifiers(balls);
  const lines = [
    HEADER('the ball catalog the server sends in the welcome packet (packages/sdk/data/balls.json)'),
    '/** Ball ids by name, e.g. `Ball.GreatBall`. */',
    'export const Ball = {',
  ];
  for (const b of keyed) lines.push(`  ${b.key}: ${b.id},`);
  lines.push('} as const;', '', 'export type BallId = (typeof Ball)[keyof typeof Ball];', '');
  lines.push(
    'export interface BallInfo {',
    '  readonly id: number;',
    '  readonly name: string;',
    '  readonly catchRate: number | null;',
    '  /** Gold price in the shop, if it is sold. */',
    '  readonly priceGold: number | null;',
    '  readonly buyable: boolean;',
    '}',
    '',
  );
  lines.push('export const BALL_CATALOG: readonly BallInfo[] = [');
  for (const b of keyed)
    lines.push(`  { id: ${b.id}, name: ${str(b.name)}, catchRate: ${b.catchRate}, priceGold: ${b.priceGold}, buyable: ${b.buyable} },`);
  lines.push('];', '');
  return lines.join('\n');
}

/** The public catalog plus the game's own items. When an id is in both, the public catalog wins. */
export function mergeItems(publicItems, extraItems) {
  const known = new Set(publicItems.map((i) => i.id));
  return [...publicItems, ...extraItems.filter((i) => !known.has(i.id))];
}

async function loadItems() {
  const response = await fetch(ITEMS_URL, { signal: AbortSignal.timeout(30_000) });
  if (!response.ok) throw new Error(`could not download ${ITEMS_URL}: HTTP ${response.status}`);
  return validateItems(JSON.parse(await response.text()));
}

const main = async () => {
  const extra = fs.existsSync(EXTRA_ITEMS_SNAPSHOT)
    ? validateItems({ items: JSON.parse(fs.readFileSync(EXTRA_ITEMS_SNAPSHOT, 'utf8')) })
    : [];
  const items = mergeItems(await loadItems(), extra);
  const balls = validateBalls(JSON.parse(fs.readFileSync(BALLS_SNAPSHOT, 'utf8')));
  const outputs = [
    [OUT_ITEMS, renderItems(items)],
    [OUT_BALLS, renderBalls(balls)],
    [OUT_NPC_SHOP, renderNpcShop(items)],
  ];
  if (check) {
    const stale = outputs
      .filter(([file, text]) => !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text)
      .map(([file]) => path.relative(ROOT, file));
    if (stale.length) {
      console.error(`out of date with the game: ${stale.join(', ')}\nrun: npm run catalog`);
      process.exit(1);
    }
    console.log('catalogs are up to date');
    return;
  }
  for (const [file, text] of outputs) fs.writeFileSync(file, text);
  console.log(`items: ${items.length}, balls: ${balls.length}`);
};

if (process.argv[1] === fileURLToPath(import.meta.url)) await main();
